import sys

def resolve_type(type_name, type_map):
    if type_name not in type_map:
        return 'errtype'
    resolved = type_map[type_name]
    while resolved != 'void' and resolved != 'errtype' and resolved in type_map:
        resolved = type_map[resolved]
    return resolved

def apply_operations(operators):
    type_map = {}
    results = []
    for operator in operators:
        if operator.startswith('typedef'):
            _, a, b = operator.split()
            if b not in type_map and b not in {'void', 'errtype'}:
                type_map[b] = a
        elif operator.startswith('typeof'):
            _, a = operator.split()
            resolved = resolve_type(a, type_map)
            if resolved == 'errtype':
                results.append('errtype')
            else:
                count_amps = 0
                count_stars = 0
                while resolved.startswith('&'):
                    count_amps += 1
                    resolved = resolved[1:]
                while resolved.endswith('*'):
                    count_stars += 1
                    resolved = resolved[:-1]
                if resolved != 'void':
                    results.append('errtype')
                else:
                    results.append('void' + '*' * (count_amps - count_stars))
    return results

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    operators = input[1:n+1]
    results = apply_operations(operators)
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
